"""Wrap an existing vkernels compiled region without copying its compute IR.

The initial adapter uses the compiler's synchronous NumPy reference path for
scalar-position GPT-2/Qwen3 decode. It keeps the prepared weight object bound
and takes the cache from the provider. Device launch and weight rebinding are
separate milestones: this adapter is never a production GPU fallback.
"""

from __future__ import annotations

from .graph import Access, AccessMode, Graph, Node, Resource, ResourceKind, plan_graph


class VkernelsReferenceRegion:
    def __init__(self, compiled, *, name: str):
        graph = compiled.graph
        if set(graph.scalars) != {"p"}:
            raise ValueError("reference region requires the compiler's scalar-position decode path")
        weights = set(compiled.weights.arrays())
        owners = {name: "weights" for name in weights}
        owners.update(k_cache="kv", v_cache="kv")
        accesses: dict[str, set[str]] = {}
        for op in graph.ops:
            for mode, regions in (("read", op.read_regions), ("write", op.write_regions)):
                for region in regions:
                    sid = region.storage_id
                    if sid in graph.fresh_storages:
                        continue
                    storage = graph.storage_names[sid]
                    if storage == "ids":
                        if mode == "write":
                            raise ValueError("region cannot mutate token IDs")
                        continue
                    if storage not in owners:
                        raise ValueError(f"external storage {storage!r} has no resource binding")
                    accesses.setdefault(owners[storage], set()).add(mode)
        modes = {frozenset({"read"}): AccessMode.READ, frozenset({"write"}): AccessMode.WRITE, frozenset({"read", "write"}): AccessMode.READ_WRITE}
        node = Node(name, name, ("ids", "position"), ("logits",), tuple(Access(resource, modes[frozenset(effects)]) for resource, effects in sorted(accesses.items())))
        self.plan = plan_graph(Graph(name, node.inputs, node.outputs, (Resource("weights", ResourceKind.WEIGHT), Resource("kv", ResourceKind.KV)), (node,), "vkernels-fp64-reference"))
        self.compiled = compiled
        self.name = name

    def __call__(self, inputs, resources):
        if resources["weights"] is not self.compiled.weights:
            raise ValueError("reference region requires its prepared weight object")
        logits, _trace = self.compiled.run(inputs["ids"], resources["kv"], inputs["position"], mode="reference")
        return {"logits": logits}

"""Owned transfer plans for model-declared state in existing kvaas row pools.

Plans retain every source and pointer table for a graph generation's lifetime.
Replacing pool or stage storage requires rebuilding the plan and its graphs.
Admission guarantees unique live destination rows; inactive rows are masked.
"""

from __future__ import annotations

import torch


class StateTransferPlan:
    """Copy or gather fixed-address state without changing floating-point bits."""

    def __init__(self, sources, layer_ids, pool, nb, rows, batch):
        self.sources = tuple(sources)
        self.pool = pool
        self.nb, self.rows, self.batch = nb, rows, batch
        self.size = sources[0][0].numel()
        self.bits = pool.element_size() * 8
        self.raw_pool = pool.view(torch.uint16 if self.bits == 16 else torch.uint32)
        self.ptrs = torch.tensor([s.data_ptr() for s in sources], dtype=torch.int64, device=pool.device)
        self.strides = torch.tensor([s.stride(0) for s in sources], dtype=torch.int64, device=pool.device)
        self.layers = torch.tensor(layer_ids, dtype=torch.int64, device=pool.device)

    @classmethod
    def create(cls, sources, layer_ids, pool, nb, rows, batch):
        """Decline unsupported layouts without allocating or touching pool bytes."""
        if not sources or len(sources) != len(layer_ids) or batch < 1:
            return None
        if pool.ndim < 3 or not pool.is_cuda or not pool.is_contiguous() or pool.dtype not in (torch.float16, torch.bfloat16, torch.float32) or pool.shape[0] == 0 or pool.shape[1] == 0 or pool[0, 0].numel() == 0:
            return None
        if len(set(layer_ids)) != len(layer_ids) or any(i < 0 or i >= pool.shape[1] for i in layer_ids):
            return None
        if any(s.ndim != pool.ndim - 1 or s.device != pool.device or s.dtype != pool.dtype or s.shape[0] < batch or tuple(s.shape[1:]) != tuple(pool.shape[2:]) or not s[0].is_contiguous() or s.stride(0) < s[0].numel() or s.untyped_storage().data_ptr() == pool.untyped_storage().data_ptr() for s in sources):
            return None
        if any(t.device != pool.device or t.dtype != torch.int64 or not t.is_contiguous() for t in (nb, rows)) or nb.numel() != 1 or rows.numel() < batch:
            return None
        return cls(sources, layer_ids, pool, nb, rows, batch)

    def _transfer(self, gather):
        from vkernels.torch_ops.state_transfer import masked_state_transfer

        masked_state_transfer(self.ptrs, self.strides, self.layers, self.raw_pool, self.nb, self.rows, size=self.size, pool_stride=self.pool.stride(0), pool_rows=self.pool.shape[0], bits=self.bits, batch=self.batch, gather=gather)

    def copy(self):
        """Write live stage rows back into their admitted pool rows."""
        self._transfer(False)

    def gather(self):
        """Load live pool rows; zero inactive stage rows without reading the pool."""
        self._transfer(True)


